'use strict';
const $=s=>document.querySelector(s);
const world=$('#world'),player=$('#player'),dialog=$('#details');
const data={
 skills:{label:'01 / THE TOOLBOX',title:'Skills',intro:'From the first prompt to the production deploy. The tools I use to turn a useful idea into a reliable product.',body:`<div class="content-block"><h3>AI & machine learning</h3><p>Building AI features that are measurable, grounded in real data, and useful to the people using them.</p><div class="tags">${['Python','LLM APIs','RAG','Embeddings','Vector databases','Model evaluation'].map(tag).join('')}</div></div><div class="content-block"><h3>Full stack development</h3><p>Accessible interfaces, dependable APIs, and data models that make room for the next iteration.</p><div class="tags">${['TypeScript','React','Next.js','Node.js','FastAPI','PostgreSQL'].map(tag).join('')}</div></div><div class="content-block"><h3>Shipping & collaboration</h3><div class="tags">${['Docker','AWS','CI/CD','Git','Automated testing','Product discovery'].map(tag).join('')}</div><p>Comfortable working across design, product, and engineering — from a quick prototype to monitoring a live service.</p></div>`},
 experience:{label:'02 / THE TIMELINE',title:'Experience',intro:'Five years connecting product thinking with hands-on engineering. All employers, dates, and achievements below are fictional examples.',body:`<div class="content-block"><span class="meta">2023 — PRESENT · FICTIONAL ROLE</span><h3>AI Full Stack Developer</h3><h4>Northstar Labs · Remote</h4><ul><li>Built a knowledge assistant that answers questions using internal documentation, with source citations and access controls.</li><li>Delivered a React workspace and Python API for reviewing AI-generated outputs.</li><li>Introduced evaluation datasets, user feedback loops, and monitoring for model quality and response time.</li></ul></div><div class="content-block"><span class="meta">2021 — 2023 · FICTIONAL ROLE</span><h3>Full Stack Developer</h3><h4>Orbit Studio · Hybrid</h4><ul><li>Developed customer dashboards with TypeScript, Node.js, and PostgreSQL.</li><li>Worked with designers to improve accessibility and simplify complex onboarding flows.</li><li>Added automated checks and repeatable deployments to help a small team ship with confidence.</li></ul></div>`},
 education:{label:'03 / THE KNOWLEDGE BASE',title:'Education',intro:'A foundation in computer science. An ongoing habit of learning by building. These are example qualifications.',body:`<div class="content-block"><span class="meta">2017 — 2021 · FICTIONAL DEGREE</span><h3>B.Sc. Computer Science</h3><h4>Example University</h4><p>Coursework in algorithms, data structures, databases, distributed systems, and machine learning.</p><p>Capstone: a semantic search engine for research papers, combining document ingestion, embeddings, and a searchable web interface.</p></div><div class="content-block"><span class="meta">CONTINUOUS LEARNING</span><h3>The next thing to understand</h3><div class="tags">${['Applied deep learning','LLM evaluation','AI system design','Human–AI interaction'].map(tag).join('')}</div><p>Regular experiments, technical reading, and small open-source contributions keep the learning practical.</p></div>`},
 projects:{label:'04 / THE BUILD LAB',title:'Projects',intro:'Three example builds at the intersection of AI and everyday work. These are portfolio concepts, not live products.',body:`<div class="content-block"><span class="meta">01 · KNOWLEDGE & SEARCH</span><h3>Atlas — your team's knowledge, connected</h3><p>A document assistant with semantic search, grounded answers, and source citations. Designed around permissions, retrieval quality, and a clear “I don't know” when evidence is missing.</p><div class="tags">${['Next.js','FastAPI','PostgreSQL + pgvector'].map(tag).join('')}</div></div><div class="content-block"><span class="meta">02 · DEVELOPER TOOLS</span><h3>CodeLens — a second pair of eyes</h3><p>An AI review workspace that summarizes pull requests and proposes improvements. Developers inspect the reasoning and approve every change.</p><div class="tags">${['TypeScript','GitHub API','LLM evaluation'].map(tag).join('')}</div></div><div class="content-block"><span class="meta">03 · WORKFLOW AUTOMATION</span><h3>FlowPilot — less repetitive work</h3><p>A workflow builder that turns incoming documents into structured records, with validation, retry handling, and a human review queue.</p><div class="tags">${['React','Python','Redis','Docker'].map(tag).join('')}</div></div>`}
};
function tag(s){return `<span class="tag">${s}</span>`}
const keys=new Set(),visited=new Set();let x=550,y=350,near=null,last=0,returnFocus=null;
const stationEls=[...document.querySelectorAll('.station')];
function positions(){const r=world.getBoundingClientRect();return stationEls.map(el=>{let b=el.getBoundingClientRect();return {id:el.dataset.station,el,x:(b.left-r.left+b.width/2)/r.width*1100,y:(b.top-r.top+b.height/2)/r.height*700,w:b.width/r.width*1100,h:b.height/r.height*700}})}
let stations=[];
function paint(){const c=$('#map'),ctx=c.getContext('2d');ctx.clearRect(0,0,1100,700);ctx.fillStyle='#19232c';ctx.fillRect(0,0,1100,700);ctx.strokeStyle='#25333e';ctx.lineWidth=1;for(let i=20;i<1100;i+=35){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,700);ctx.stroke()}for(let j=0;j<700;j+=35){ctx.beginPath();ctx.moveTo(0,j);ctx.lineTo(1100,j);ctx.stroke()}ctx.strokeStyle='#35444f';ctx.lineWidth=50;ctx.lineCap='square';ctx.beginPath();ctx.moveTo(245,245);ctx.lineTo(245,350);ctx.lineTo(850,350);ctx.lineTo(850,240);ctx.moveTo(245,350);ctx.lineTo(245,480);ctx.moveTo(850,350);ctx.lineTo(850,480);ctx.stroke();ctx.strokeStyle='#718074';ctx.lineWidth=1;ctx.setLineDash([5,12]);ctx.beginPath();ctx.moveTo(245,350);ctx.lineTo(850,350);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#586751';ctx.lineWidth=1;ctx.strokeRect(517,317,66,66);ctx.fillStyle='#263632';ctx.fillRect(525,325,50,50);ctx.fillStyle='#839271';for(const [a,b]of[[40,55],[1060,55],[40,645],[1060,645]]){ctx.fillRect(a-7,b,15,1);ctx.fillRect(a,b-7,1,15)}stations=positions();}
function render(){player.style.left=`${x/11}%`;player.style.top=`${y/7}%`;let closest=null,dist=Infinity;for(const s of stations){let dx=Math.max(Math.abs(x-s.x)-s.w/2,0),dy=Math.max(Math.abs(y-s.y)-s.h/2,0),d=Math.hypot(dx,dy);if(d<85&&d<dist){closest=s.id;dist=d}}near=closest;stationEls.forEach(el=>el.classList.toggle('near',el.dataset.station===near));$('#prompt').textContent=near?`[ E ] Explore ${data[near].title}`:'Move closer to a station to explore';$('#prompt').classList.toggle('active',!!near);$('#touchExplore').disabled=!near;}
function openSection(id){keys.clear();player.classList.remove('moving');visited.add(id);const d=data[id];$('#dialogEyebrow').textContent=d.label;$('#dialogContent').innerHTML=`<h2>${d.title}</h2><p class="content-intro">${d.intro}</p>${d.body}`;showDialog();updateProgress()}
function showDialog(){returnFocus=document.activeElement;dialog.showModal();dialog.scrollTop=0;$('#closeDialog').focus()}
function updateProgress(){$('#count').textContent=`${visited.size} / 4`;$('#progress').style.width=`${visited.size*25}%`;for(const id of visited){let el=$(`[data-station="${id}"]`);el.classList.add('visited');el.querySelector('.station-visit').textContent='✓ AREA EXPLORED'}if(visited.size===4)$('#completion').textContent='World explored. Thanks for getting to know my work!'}
function closeDialog(){dialog.close();keys.clear();if(returnFocus?.isConnected)returnFocus.focus();else world.focus()}
$('#closeDialog').onclick=closeDialog;$('#backToMap').onclick=closeDialog;dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
stationEls.forEach(el=>el.querySelector('button').onclick=()=>openSection(el.dataset.station));
$('#readResume').onclick=()=>{$('#dialogEyebrow').textContent='PLAYER ONE / COMPLETE RÉSUMÉ';$('#dialogContent').innerHTML=`<h2>Alex Morgan</h2><p class="content-intro">AI Full Stack Developer · Fictional sample profile<br>Building thoughtful web products with applied AI.</p>`+Object.values(data).map(d=>`<section class="content-block"><h2>${d.title}</h2><p>${d.intro}</p>${d.body}</section>`).join('');keys.clear();showDialog()};
$('#reset').onclick=()=>{x=550;y=350;keys.clear();render();world.focus()};
$('#touchExplore').onclick=()=>{if(near)openSection(near)};
const mapKeys={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
window.addEventListener('keydown',e=>{if(dialog.open||e.ctrlKey||e.metaKey||e.altKey)return;if(mapKeys[e.code]){e.preventDefault();keys.add(mapKeys[e.code]);}else if(e.code==='KeyE'||(e.code==='Enter'&&document.activeElement===world)){e.preventDefault();if(near&&!e.repeat)openSection(near)}});window.addEventListener('keyup',e=>keys.delete(mapKeys[e.code]));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.dir)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.dir))});
function loop(t){let dt=Math.min((t-last)/1000,.04);last=t;if(!dialog.open){let dx=Number(keys.has('right'))-Number(keys.has('left')),dy=Number(keys.has('down'))-Number(keys.has('up'));let m=Math.hypot(dx,dy);if(m){let nx=Math.max(30,Math.min(1070,x+dx/m*220*dt)),ny=Math.max(65,Math.min(635,y+dy/m*220*dt));const blocked=(a,b)=>stations.some(s=>Math.abs(a-s.x)<s.w/2+12&&Math.abs(b-s.y)<s.h/2+15);if(!blocked(nx,y))x=nx;if(!blocked(x,ny))y=ny;render()}player.classList.toggle('moving',!!m)}requestAnimationFrame(loop)}
new ResizeObserver(()=>{paint();render()}).observe(world);paint();render();requestAnimationFrame(loop);
